import {Studio} from './store.js';
import {zip} from './zip.js';
let studio;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cfg,current,anim,frame=0,playing=false,last=0,page=0,total=0,items=[],selected=new Set(),stats,edition=0;
async function api(path,body){return studio.api(path,body)}
function error(e){$('error').textContent=e.message;$('error').hidden=false}
async function task(fn){$('error').hidden=true;$('busy').hidden=false;$('busy').querySelector('b').textContent='Computing in your browser…';try{return await fn()}catch(e){error(e)}finally{$('busy').hidden=true}}
function options(id,values,def){$(id).replaceChildren(...values.map(([v,l])=>{let o=document.createElement('option');o.value=v;o.textContent=l;return o}));if(def&&values.some(([v])=>v===def))$(id).value=def}
function save(data,name,type='text/plain'){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.hidden=true;document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(u)},1000)}
async function download(path,body,name){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error((await r.json()).error);let b=await r.blob();save(b,name,b.type)}
function show(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('section-label').textContent=({lab:'ART LABORATORY',dna:'DNA INSPECTOR',animation:'ANIMATION STUDIO',collection:'COLLECTION EXPLORER',analytics:'ANALYTICS',dashboard:'DASHBOARD'})[view];location.hash=view;if(view==='collection')task(collection);if(view==='analytics')task(analytics);if(view==='dna')dna();window.scrollTo(0,0)}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));
function familyControls(){let f=$('family').value;options('subject',cfg.subjects[f].map(s=>[s,s]));options('style',cfg.traits.filter(t=>t.families.length===1&&t.families[0]===f).map(t=>[t.id,t.id+' · '+t.label]),{SKULLS:'S031',CHARACTERS:'C081',ANIMALS:'A091'}[f])}

function syncControls(g){$('family').value=g.family;familyControls();for(const [id,value] of Object.entries({subject:g.subject,rarity:g.rarity,style:g.style,appearance:g.appearance,camera:g.modifiers.T01,lighting:g.modifiers.T03,glyph:g.modifiers.T05,seed:g.seed,profile:String(g.animation.profile)}))$(id).value=value;for(const n of ['entropy','fragmentation','complexity','contrast']){$(n).value=g.parameters[n];$(n+'-out').value=(+g.parameters[n]).toFixed(2)}$('profile').disabled=!g.animation.enabled;$('fragmentation').disabled=!['FRAGMENTED','APPARENT CHAOS'].includes(g.appearance)}
function packet(p,e=0){current=p;edition=e;anim=null;playing=false;$('play').textContent='Play';let g=p.genome;if(e)syncControls(g);$('lab-art').src=p.preview;$('hero-art').src=p.preview;$('lab-name').textContent=g.subject+' / '+g.rarity;$('specimen-name').textContent=cfg.traits.find(t=>t.id===g.style)?.label||g.subject;$('specimen-info').textContent=g.family+' · '+g.rarity+' · '+g.appearance;$('specimen-id').textContent=e?'EDITION / '+String(e).padStart(4,'0'):'LAB / '+p.id.slice(0,6).toUpperCase();$('lab-time').textContent=p.performance.render_ms!=null?p.performance.render_ms.toFixed(1)+' MS '+p.performance.backend.toUpperCase():'STORED CANONICAL';$('lab-backend').textContent=p.performance.backend;$('geom-count').textContent=(p.operators.length||'Stored')+' operators';$('ascii-preview').textContent=p.ascii;dna();draw()}
async function generate(){const f=new FormData($('lab-form')),o={};for(let k of ['subject','style','appearance','camera','lighting','glyph'])o[k]=f.get(k);for(let k of ['entropy','fragmentation','complexity','contrast'])if(f.get(k)!==null)o[k]=+f.get(k);packet(await api('/api/generate',{family:f.get('family'),rarity:f.get('rarity'),seed:f.get('seed'),profile:+f.get('profile'),overrides:o}));await status()}
$('lab-form').onsubmit=e=>{e.preventDefault();task(generate)};$('family').onchange=familyControls;$('appearance').onchange=()=>{$('fragmentation').disabled=!['FRAGMENTED','APPARENT CHAOS'].includes($('appearance').value)};$('rarity').onchange=()=>{$('profile').disabled=$('rarity').value!=='LEGENDARY'};
for(const n of ['entropy','fragmentation','complexity','contrast'])$(n).oninput=()=>$(n+'-out').value=(+$(n).value).toFixed(2);
$('new-seed').onclick=()=>{$('seed').value=Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16).padStart(8,'0')).join('')};
$('hero-lab').onclick=()=>show('lab');$('open-dna').onclick=()=>show('dna');$('download-ascii').onclick=()=>current&&save(current.ascii,'null-genesis.txt');
$('download-png').onclick=()=>current&&task(async()=>{const r=await fetch(current.preview);save(await r.blob(),'null-genesis.png','image/png')});
$('save-dna').onclick=()=>current&&save(JSON.stringify(current.dna||current.genome,null,2),'null-genesis.dna.json','application/json');
$('regenerate').onclick=()=>current&&task(async()=>packet(await api('/api/regenerate',{genome:current.genome}),edition));
$('reveal').onclick=()=>current&&task(async()=>{packet(await api('/api/reveal',edition?{edition,reveal:true}:{id:current.id,reveal:true}),edition);show('lab')});
$('import-dna').onchange=async e=>{let f=e.target.files[0];if(!f)return;await task(async()=>{if(f.size>2_000_000)throw Error('DNA files must be under 2 MB.');let g=JSON.parse(await f.text());packet(await api(g.algorithm==='AES-256-GCM'?'/api/decode':'/api/regenerate',g.algorithm==='AES-256-GCM'?{envelope:g}:{genome:g}));show('dna')});e.target.value=''};
function summaries(id,values){$(id).innerHTML=values.map(([a,b])=>'<div><small>'+esc(a)+'</small><b>'+esc(b)+'</b></div>').join('')}
function dna(){if(!current)return;let g=current.genome;summaries('dna-summary',[['GENOME VERSION',g.genome_version],['SEED / 256 BIT',g.seed],['STRUCTURAL FINGERPRINT',g.fingerprint],['ENCRYPTION',g.encryption]]);$('genome-json').textContent=JSON.stringify(current.dna||g,null,2)}
async function status(){
 const s=await api('/api/status'),h=s.hardware,c=s.collection;
 $('count').textContent='3,333';$('remaining').textContent='All editions accepted and verified';$('percent').textContent='100%';$('progress').style.width='100%';
 $('device').textContent=h.device;$('device-small').textContent=h.backend+' · browser renderer';$('backend-label').textContent=h.backend.toUpperCase()+' / WEB';$('cuda-state').textContent=h.backend==='WebGPU'?'GPU ACTIVE':'CPU WORKER';$('cuda-state').title=h.reason||'';
 $('vram').textContent='900 cells';$('gpu-ms').textContent=h.last_gpu_ms==null?'Ready':h.last_gpu_ms.toFixed(1)+' ms';$('rejected').textContent='3,333';
 $('quotas').innerHTML=Object.entries(c.rarity).map(([r,v])=>'<div class="quota-row"><span>'+r+'</span><div class="track"><i style="width:100%"></i></div><span class="quota-count">'+v.count+' / '+v.quota+'</span></div>').join('');
 $('job-status').textContent='Collection rendered with NVIDIA CUDA. New laboratory art runs in this browser.'+(h.reason?' CPU fallback: '+h.reason:'');return s;
}
$('resume').onclick=()=>show('lab');$('pause-generation').onclick=()=>show('collection');
$('audit').onclick=()=>task(async()=>{let r=await api('/api/audit',{});$('job-status').textContent=r.passed?'Audit passed: '+r.supply+' editions; canonical records and animations verified.':r.errors.join(' · ')});
async function openEdition(e){packet(await api('/api/item?edition='+e),e);show('lab')}
function query(){return new URLSearchParams({page,limit:24,family:$('filter-family').value,rarity:$('filter-rarity').value,trait:$('filter-trait').value,search:$('search').value,sort:$('sort').value})}
async function collection(){let d=await api('/api/collection?'+query());items=d.items;total=d.total;$('results-label').textContent=total.toLocaleString()+' editions · '+selected.size+' selected';$('collection-description').textContent='Browse '+total.toLocaleString()+' matching editions. Original artwork, metadata and DNA are available for export.';
$('collection-grid').innerHTML=items.map(m=>'<article class="collection-card"><input class="card-select" type="checkbox" aria-label="Select edition '+m.edition+'" data-select="'+m.edition+'" '+(selected.has(m.edition)?'checked':'')+'><img loading="lazy" src="/collection/previews/'+String(m.edition).padStart(4,'0')+'.png" alt="'+esc(m.primary_style)+'" data-open="'+m.edition+'"><div class="card-title"><span>#'+String(m.edition).padStart(4,'0')+'</span><span class="badge">'+m.rarity+'</span></div><small>'+esc(m.subject)+' / '+m.family+'<br>'+esc(m.primary_style)+'<br>RANK '+(m.rank||'—')+' · QUALITY '+m.quality.quality_score+'</small><div class="card-actions"><button data-open="'+m.edition+'">Inspect ↗</button><a class="file-button" href="#" data-export="'+m.edition+'">Export</a>'+(m.animation?'<button data-animate="'+m.edition+'">Play</button>':'')+'</div></article>').join('');
$('page-label').textContent='PAGE '+(page+1)+' / '+Math.max(1,Math.ceil(total/24));$('page-prev').disabled=page===0;$('page-next').disabled=(page+1)*24>=total;
document.querySelectorAll('[data-export]').forEach(b=>b.onclick=e=>{e.preventDefault();task(()=>exportItems([+b.dataset.export]))});
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>task(()=>openEdition(+b.dataset.open)));
document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{let n=+b.dataset.select;b.checked?selected.add(n):selected.delete(n);$('results-label').textContent=total.toLocaleString()+' editions · '+selected.size+' selected'});
document.querySelectorAll('[data-animate]').forEach(b=>b.onclick=()=>task(async()=>{await openEdition(+b.dataset.animate);$('legend-choice').value=b.dataset.animate;show('animation');await loadAnimation()}))}
for(const id of ['filter-family','filter-rarity','filter-trait','sort'])$(id).onchange=()=>{page=0;task(collection)};let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{page=0;task(collection)},300)};
$('page-prev').onclick=()=>{page--;task(collection)};$('page-next').onclick=()=>{page++;task(collection)};$('select-page').onclick=()=>{items.forEach(m=>selected.add(m.edition));task(collection)};
$('export-selected').onclick=()=>task(async()=>{if(!selected.size)throw Error('Select editions first.');await exportItems([...selected])});$('export-all').onclick=()=>task(allExports);
async function recent(){let d=await api('/api/collection?limit=6&sort=quality');$('recent').innerHTML=d.items.map(m=>'<div class="recent-card" data-recent="'+m.edition+'"><img src="/collection/previews/'+String(m.edition).padStart(4,'0')+'.png" alt="'+esc(m.subject)+'"><p>#'+String(m.edition).padStart(4,'0')+' / '+esc(m.subject)+'</p><small>'+m.family+' · '+m.rarity+'</small></div>').join('');document.querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>task(()=>openEdition(+b.dataset.recent)));let l=await api('/api/collection?rarity=LEGENDARY&limit=23');options('legend-choice',[['','Laboratory entity'],...l.items.map(m=>[String(m.edition),'#'+String(m.edition).padStart(4,'0')+' · '+m.animation_profile])])}
async function loadAnimation(){let e=$('legend-choice').value;if(e){packet(await api('/api/item?edition='+e),+e);anim=await api('/collection/animations/'+String(e).padStart(4,'0')+'.frames.json')}else{if(!current)throw Error('Construct an entity first.');anim=await api('/api/animation',{id:current.id,reveal:!current.genome.animation.enabled});edition=0}frame=0;playing=false;$('play').textContent='Play';$('timeline').max=anim.frames.length-1;$('animation-name').textContent=anim.profile==='STATIC'?'Interactive reconstruction reveal':anim.profile;$('animation-facts').textContent=anim.frames.length+' native frames\n'+anim.fps+' FPS · '+anim.seconds+' second loop\n30 columns × 30 rows\nStable 3D surface identities\nCanonical ASCII + grayscale luminance';$('animation-facts').style.whiteSpace='pre-line';draw()}
$('load-animation').onclick=()=>task(loadAnimation);$('legend-choice').onchange=()=>{anim=null;playing=false;task(loadAnimation)};
function draw(){let ctx=$('animation-canvas').getContext('2d');ctx.fillStyle='#050505';ctx.fillRect(0,0,390,720);if(!current)return;let text=anim?anim.frames[frame]:current.ascii,levels=anim?anim.luminance[frame]:current.luminance,chars=text.split('\n').slice(0,30).join('');ctx.font='24px Consolas,monospace';ctx.textBaseline='top';for(let i=0;i<900;i++){let v=Math.round(levels[i]);ctx.fillStyle='rgb('+v+','+v+','+v+')';ctx.fillText(chars[i],i%30*13,Math.floor(i/30)*24)}if($('show-grid').checked){ctx.strokeStyle='#ffffff16';ctx.lineWidth=.5;for(let x=0;x<=30;x++){ctx.beginPath();ctx.moveTo(x*13,0);ctx.lineTo(x*13,720);ctx.stroke()}for(let y=0;y<=30;y++){ctx.beginPath();ctx.moveTo(0,y*24);ctx.lineTo(390,y*24);ctx.stroke()}}$('timeline').value=frame;$('frame-label').textContent=frame+' / '+(anim?anim.frames.length-1:95);$('timeline-seconds').textContent=(frame/(anim?.fps||12)).toFixed(2)+' SEC'}
$('play').onclick=()=>task(async()=>{if(!anim)await loadAnimation();playing=!playing;$('play').textContent=playing?'Pause':'Play';last=performance.now()});
$('timeline').oninput=()=>{playing=false;$('play').textContent='Play';frame=+$('timeline').value;if(anim)draw()};
function step(d){if(!anim)return;playing=false;$('play').textContent='Play';frame=(frame+d+anim.frames.length)%anim.frames.length;draw()}
$('prev-frame').onclick=()=>step(-1);$('next-frame').onclick=()=>step(1);$('show-grid').onchange=draw;
function tick(t){if(playing&&anim&&t-last>=1000/(anim.fps*+$('speed').value)){frame++;if(frame>=anim.frames.length){frame=0;if(!$('loop').checked){playing=false;$('play').textContent='Play'}}last=t;draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);
$('export-animation').onclick=()=>task(async()=>{
 if(!anim)await loadAnimation();let f=$('animation-format').value;
 if(edition&&f==='frames'){save(JSON.stringify(anim),'null-genesis-'+edition+'.frames.json','application/json');return}if(edition){let path='/collection/animations/'+String(edition).padStart(4,'0')+'.'+(f==='frames'?'frames.json':f);save(await fetch(path).then(r=>{if(!r.ok)throw Error('Export not available.');return r.blob()}),'null-genesis-'+edition+'.'+(f==='frames'?'frames.json':f));return}
 if(f==='frames'){save(JSON.stringify(anim),'null-genesis.frames.json','application/json');return}
 if(f==='html'){save(animationHTML(anim),'null-genesis.animation.html','text/html');return}
 await recordVideo(f);
});
function chart(id,data){let sum=Object.values(data).reduce((a,b)=>a+b,0);$(id).innerHTML=Object.entries(data).map(([name,n])=>'<div class="chart-row"><div class="row"><span>'+name+'</span><span>'+n+' · '+(100*n/Math.max(sum,1)).toFixed(1)+'%</span></div><div class="track"><i style="width:'+100*n/Math.max(sum,1)+'%"></i></div></div>').join('')}
async function analytics(){stats=await api('/api/analytics');chart('family-chart',stats.family);chart('rarity-chart',stats.rarity);summaries('analytics-summary',[['ACCEPTED',stats.accepted],['UNIQUE COMBINATIONS',stats.unique_combinations],['UNUSED CURATED VALUES',stats.unused_traits.length],['MEAN QUALITY',stats.quality_mean?.toFixed(2)||'—']]);traitTable()}
function traitTable(){if(!stats)return;let q=$('trait-search').value.toLowerCase();$('trait-body').innerHTML=stats.traits.filter(t=>(t.id+' '+t.label+' '+t.category).toLowerCase().includes(q)).sort((a,b)=>b.count-a.count||a.id.localeCompare(b.id)).map(t=>'<tr><td>'+esc(t.id)+'</td><td>'+esc(t.label)+'</td><td>'+esc(t.category)+'</td><td>'+t.count+'</td><td>'+t.percentage+'%</td></tr>').join('')}
$('trait-search').oninput=traitTable;
task(async()=>{studio=await new Studio().init();cfg=await api('/api/config');options('family',cfg.families.map(f=>[f,f]),'SKULLS');options('rarity',cfg.rarities.map(r=>[r,r]),'RARE');familyControls();options('appearance',cfg.modes.map(m=>[m,m]),'RECOGNIZABLE');$('fragmentation').disabled=true;for(let [id,prefix,def] of [['camera','T01','T01.02'],['lighting','T03','T03.01'],['glyph','T05','T05.10']])options(id,cfg.traits.filter(t=>t.id.startsWith(prefix+'.')).map(t=>[t.id,t.label]),def);options('profile',cfg.config.legends.map((s,i)=>[String(i),s]));$('profile').disabled=true;options('filter-family',[['','All families'],...cfg.families.map(f=>[f,f])]);options('filter-rarity',[['','All rarities'],...cfg.rarities.map(r=>[r,r])]);options('filter-trait',[['','All traits'],...cfg.traits.map(t=>[t.id,t.id+' · '+t.label])]);await status();await recent();packet(await api('/api/item?edition=0006'),6);let v=location.hash.slice(1);if(['lab','dna','animation','collection','analytics'].includes(v))show(v);});

$('load-key').onchange=e=>task(async()=>{const f=e.target.files[0];if(!f)return;await studio.loadKey(f);$('key-status').textContent='Owner key loaded in browser memory.';e.target.value=''});
$('clear-key').onclick=()=>{studio.key=null;studio.authenticatedDNA?.clear();$('key-status').textContent='No owner key loaded.'};
async function exportItems(editions){
 if(editions.length>100)throw Error('Export up to 100 selected editions at a time, or use the complete collection archives.');
 const files=[];for(const e of editions){document.querySelector('#busy b').textContent='Preparing edition '+e+'…';const a=await studio.repo.item(e),dir=String(e).padStart(4,'0')+'/';files.push([dir+'art.txt',a.ascii],[dir+'metadata.json',JSON.stringify(a.metadata,null,2)],[dir+'dna.json',JSON.stringify(a.dna,null,2)],[dir+'scene.json',JSON.stringify({scene:a.scene,config:a.cfg})]);const png=await fetch('/collection/previews/'+String(e).padStart(4,'0')+'.png').then(r=>r.arrayBuffer());files.push([dir+'preview.png',new Uint8Array(png)]);}
 save(zip(files),'null-genesis-editions.zip','application/zip');
}
async function allExports(){
 const list=await fetch('/exports/index.json').then(r=>r.json());$('archive-list').replaceChildren(...list.map(a=>{const link=document.createElement('a');link.className='file-button';link.href=a.url;link.download=a.name;link.textContent=a.label+' · '+a.megabytes+' MB';return link}));$('archive-dialog').showModal();
}
function animationHTML(a){
 const payload=JSON.stringify(a).replace(/</g,'\\u003c');
 return '<!doctype html><meta charset="utf-8"><title>NULL GENESIS · Reconstruction</title><style>body{background:#111;color:#ccc;font:13px monospace;text-align:center}canvas{display:block;margin:20px auto;height:80vh;max-width:100%;background:#050505}button,input{margin:8px;accent-color:#ccc}a{color:#ccc}</style><h1>NULL GENESIS</h1><canvas id="c" width="390" height="720"></canvas><button id="play">Pause</button><input id="t" type="range" min="0" max="95" value="0"><script>const a='+payload+';let n=0,p=true;const c=document.querySelector("#c"),x=c.getContext("2d"),t=document.querySelector("#t");function draw(){x.fillStyle="#050505";x.fillRect(0,0,390,720);x.font="24px Consolas,monospace";x.textBaseline="top";const s=a.frames[n].split("\\n").slice(0,30).join("");for(let i=0;i<900;i++){let v=Math.round(a.luminance[n][i]);x.fillStyle="rgb("+v+","+v+","+v+")";x.fillText(s[i],i%30*13,Math.floor(i/30)*24)}t.value=n}document.querySelector("#play").onclick=e=>{p=!p;e.target.textContent=p?"Pause":"Play"};t.oninput=()=>{p=false;n=+t.value;draw()};draw();setInterval(()=>{if(p){n=(n+1)%96;draw()}},1000/a.fps);<\/script>';
}
async function recordVideo(format){
 if(!window.MediaRecorder)throw Error('Video recording is unavailable. Export interactive HTML or native frames.');
 const mime=format==='mp4'?'video/mp4':'video/webm';if(!MediaRecorder.isTypeSupported(mime))throw Error('This browser cannot encode '+format.toUpperCase()+'. Choose WebM, interactive HTML or native frames.');
 const old=frame;playing=false;$('play').textContent='Play';const stream=$('animation-canvas').captureStream(12),recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:3000000}),chunks=[];recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);const done=new Promise(resolve=>recorder.onstop=resolve);recorder.start();for(let i=0;i<96;i++){frame=i;draw();document.querySelector('#busy b').textContent='Recording frame '+(i+1)+' / 96';await new Promise(r=>setTimeout(r,1000/12));}recorder.stop();await done;stream.getTracks().forEach(t=>t.stop());save(new Blob(chunks,{type:mime}),'null-genesis.'+format,mime);frame=old;draw();
}
